CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE avatar_source_kind AS ENUM ('nickname', 'conversation');
CREATE TYPE question_status AS ENUM ('draft', 'published', 'closed');
CREATE TYPE throttle_action AS ENUM ('invite', 'participant_login', 'admin_login', 'pin_reset');
CREATE TYPE audit_outcome AS ENUM ('success', 'failure');

CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 100), invite_code_hash text NOT NULL, registration_open boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, nickname_display text NOT NULL, nickname_key text NOT NULL, nickname_rule_version text NOT NULL DEFAULT 'nickname-key-v1', pin_hash text NOT NULL, auth_version integer NOT NULL DEFAULT 1 CHECK (auth_version >= 1), current_avatar_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id, nickname_key));
CREATE INDEX participants_event_idx ON participants(event_id);
CREATE TABLE avatar_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES participants(id) ON DELETE CASCADE, source_kind avatar_source_kind NOT NULL, source_version text NOT NULL, source_digest text NOT NULL, generator_version text NOT NULL, catalog_version text NOT NULL, selected_traits jsonb NOT NULL, supersedes_id uuid REFERENCES avatar_assignments(id), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE participants ADD CONSTRAINT participants_current_avatar_fk FOREIGN KEY (current_avatar_id) REFERENCES avatar_assignments(id);
CREATE INDEX avatar_participant_idx ON avatar_assignments(participant_id);
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, prompt text NOT NULL CHECK (char_length(btrim(prompt)) BETWEEN 1 AND 500), status question_status NOT NULL DEFAULT 'draft', published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX questions_one_published_uq ON questions(event_id) WHERE status = 'published';
CREATE TABLE answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES participants(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE, content text NOT NULL CHECK (char_length(btrim(content)) BETWEEN 1 AND 1000), submitted_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(participant_id, question_id));
CREATE TABLE participant_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES participants(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_hash text NOT NULL, auth_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX participant_sessions_owner_idx ON participant_sessions(participant_id);
CREATE TABLE admin_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, username text NOT NULL, password_hash text NOT NULL, auth_version integer NOT NULL DEFAULT 1 CHECK (auth_version >= 1), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id, username));
CREATE TABLE admin_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL REFERENCES admin_accounts(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_hash text NOT NULL, auth_version integer NOT NULL, authenticated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX admin_sessions_owner_idx ON admin_sessions(admin_id);
CREATE TABLE pin_reset_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES participants(id) ON DELETE CASCADE, code_hash text NOT NULL, failure_count integer NOT NULL DEFAULT 0 CHECK (failure_count BETWEEN 0 AND 5), expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz, created_by_admin_id uuid NOT NULL REFERENCES admin_accounts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pin_reset_participant_idx ON pin_reset_grants(participant_id);
CREATE TABLE auth_throttles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action throttle_action NOT NULL, subject_key_hash text NOT NULL, failure_count integer NOT NULL DEFAULT 0, window_started_at timestamptz NOT NULL DEFAULT now(), blocked_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(action, subject_key_hash));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, admin_id uuid REFERENCES admin_accounts(id), action text NOT NULL, target_participant_id uuid REFERENCES participants(id), outcome audit_outcome NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_event_time_idx ON audit_events(event_id, created_at);
